/* Whetstone as a sliced job, included once per precision by k_whet_d.c / k_whet_f.c. Own code, CC0.
 *
 * whet_d.c / whet_f.c are Painter Engineering's whetstone.c (netlib), generated by gen.py: main() renamed, its two
 * time(0) calls kept (time() answers microseconds here) and saved, and a checksum of the final values saved. The
 * single build is the same text with double -> float, every literal an f literal and the f32-only libm of fmath.c.
 * A slice is one pass of LOOP = unit major loops (100 KWhetstones each). The first slice always has LOOP = 1, so its
 * checksum is the same on every run and the harness pins it. MWIPS = 100 * LOOPs / seconds / 1000. */
#include "bench.h"

#define PASTE(a, b) a##b
#define CAT(a, b) PASTE(a, b)
extern int CAT(WH_, MAIN)(int argc, char **argv);
extern long CAT(WH_, T0), CAT(WH_, T1);
extern CHK_T CAT(WH_, CHK);

static slicer sl;
static double first_chk, last_chk;
static int finite_ok;

static void begin(void) { sl_begin(&sl, 1, 1000); first_chk = 0; last_chk = 0; finite_ok = 1; }

static int step(void) {
    char loops[12];
    snprintf(loops, sizeof loops, "%u", sl_unit(&sl));
    char *argv[] = { "whet", loops, 0 };
    rt_out_reset();
    CAT(WH_, MAIN)(2, argv);
    double c = (double)CAT(WH_, CHK);
    if (!(c == c) || c > 1e9 || c < -1e9) finite_ok = 0;
    if (!sl.slices) first_chk = c;
    last_chk = c;
    sl_note(&sl, (u32)(CAT(WH_, T1) - CAT(WH_, T0)));
    return sl_more(&sl);
}

static void finish(bench_res *r) {
    res_clear(r);
    res_check(r, finite_ok && first_chk > 0.5 && first_chk < 1e5, finite_ok ? "checksum in range" : "NON-FINITE RESULT");
    if (sl.clocked && sl.us) res_val(r, NAME, "MWIPS", sl.work * 100000000ull / sl.us);
    res_val(r, NAME "_chk", "checksum of the LOOP=1 pass", (u64)(first_chk * 1000.0));
}

const bench_job JOB = { NAME, LABEL, begin, step, finish };
